static List<String> bfs(Map<String,List<String>> 
g,String s) {
  Queue<String> q=new ArrayDeque<>();Set<String> 
seen=new HashSet<>();
  List<String> out=new 
ArrayList<>();q.add(s);seen.add(s);
  while(!q.isEmpty()){
    String v=q.remove();out.add(v);
    for(String w:g.getOrDefault(v,List.of()))
      if(seen.add(w))q.add(w);
  }return out;
